<script>
(function(){document.querySelectorAll('.wstradesman__kar').forEach(function(k){
  var w=document.createElement('div');w.className='wstradesman__karw';k.parentNode.insertBefore(w,k);w.appendChild(k);
  ['l','d'].forEach(function(s){var b=document.createElement('button');b.type='button';b.className='wstradesman__pus wstradesman__pus--'+s;b.setAttribute('aria-label',s==='l'?'Предишно':'Следващо');b.innerHTML=s==='l'?'&#8249;':'&#8250;';
